def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)
            if float(opp.get('budget', 0)) > 500:
                rich_opp += 1
            if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 10)) <= 4:
                urgent_opp += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive:
        return min(budget, 18.0)

    slots = max(1, int(supply // WATER_REQ))
    low_supply = slots <= 1

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    survival_mode = hp <= 3 or no_water >= 2
    caution_mode = hp <= 5 or no_water >= 1

    if survival_mode:
        base = max(82.0, highest_prev + 6.0)
        if low_supply:
            base += 10.0
        if rich_opp >= 2:
            base += 8.0
        return min(budget, base)

    if caution_mode:
        base = max(58.0, avg_prev + 3.0)
        if low_supply:
            base += 10.0
        if urgent_opp >= 2:
            base += 6.0
        return min(budget, base)

    if low_supply:
        if highest_prev >= 120.0:
            base = 24.0
        else:
            base = max(46.0, highest_prev + 2.0)
        if rich_opp >= 2:
            base += 4.0
    else:
        if highest_prev >= 120.0:
            base = 16.0
        elif highest_prev >= 80.0:
            base = 28.0
        else:
            base = max(22.0, avg_prev * 0.6 + 6.0)

    if day >= 8 and hp >= 7 and budget < 200:
        base *= 0.9

    reserve_floor = 12.0 if hp >= 6 else 0.0
    bid = min(budget - reserve_floor if budget > reserve_floor else budget, base)
    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 80.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.5)

    if supply < 18:
        return min(my_status['budget'], avg_prev_bid * 1.1)

    return min(my_status['budget'], max(20.0, avg_prev_bid * 0.8))
